            self.execution_receipt(GAMMA, moment=225,
                                   post_digest="e2" * 32),
        ], moment=250)
        self.assert_convergence_invalid(self.chain(self.first, stale))
        self.assert_convergence_invalid(self.chain(self.second, self.first))

