        with self.assertRaises(TypeError):
            self.certify([{"seq": "1", "previous": None,
                           "confirmation": self.first}])
        with self.assertRaises(TypeError):
            self.certify([{"seq": 1, "previous": 7,
                           "confirmation": self.first}])
        with self.assertRaises(TypeError):
            self.certify([{"seq": 1, "previous": None,
                           "confirmation": "x"}])
